use rusqlite::{params, Connection};
use serde::Serialize;
use std::{fs, path::PathBuf, sync::Mutex};
use tauri::{Manager, State};

struct AppDb(Mutex<Connection>);
#[derive(Serialize)] struct Subject { id: i64, name: String, topic_count: i64 }
#[derive(Serialize)] struct Topic { id: i64, subject_id: i64, name: String, resource_count: i64 }
#[derive(Serialize)] struct Resource { id: i64, topic_id: i64, kind: String, title: String, content: String, path: String, updated_at: String }
fn lock_db<'a>(state: &'a State<'a, AppDb>) -> Result<std::sync::MutexGuard<'a, Connection>, String> { state.0.lock().map_err(|e| e.to_string()) }
fn init_schema(conn: &Connection) -> Result<(), String> {
  conn.execute_batch("PRAGMA foreign_keys=ON;
    CREATE TABLE IF NOT EXISTS subjects(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
    CREATE TABLE IF NOT EXISTS topics(id INTEGER PRIMARY KEY AUTOINCREMENT,subject_id INTEGER NOT NULL,name TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(subject_id,name),FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE);
    CREATE TABLE IF NOT EXISTS resources(id INTEGER PRIMARY KEY AUTOINCREMENT,topic_id INTEGER NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('note','document','video','link','image')),title TEXT NOT NULL,content TEXT NOT NULL DEFAULT '',path TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(topic_id) REFERENCES topics(id) ON DELETE CASCADE);
    CREATE INDEX IF NOT EXISTS idx_topics_subject ON topics(subject_id);
    CREATE INDEX IF NOT EXISTS idx_resources_topic_kind ON resources(topic_id,kind);") .map_err(|e| e.to_string())
}
#[tauri::command] fn initialize_database(state: State<'_, AppDb>) -> Result<(), String> { init_schema(&*lock_db(&state)?) }
#[tauri::command] fn list_subjects(state: State<'_, AppDb>) -> Result<Vec<Subject>, String> {
 let conn=lock_db(&state)?; let mut stmt=conn.prepare("SELECT s.id,s.name,COUNT(t.id) FROM subjects s LEFT JOIN topics t ON t.subject_id=s.id GROUP BY s.id ORDER BY s.name COLLATE NOCASE").map_err(|e|e.to_string())?;
 let rows=stmt.query_map([],|r|Ok(Subject{id:r.get(0)?,name:r.get(1)?,topic_count:r.get(2)?})).map_err(|e|e.to_string())?;
 rows.collect::<Result<Vec<_>,_>>().map_err(|e|e.to_string())
}
#[tauri::command] fn create_subject(name:String,state:State<'_,AppDb>)->Result<Subject,String>{let name=name.trim();if name.is_empty(){return Err("El nombre no puede estar vacío".into())}let conn=lock_db(&state)?;conn.execute("INSERT INTO subjects(name) VALUES(?1)",[name]).map_err(|e|e.to_string())?;let id=conn.last_insert_rowid();Ok(Subject{id,name:name.into(),topic_count:0})}
#[tauri::command] fn rename_subject(id:i64,name:String,state:State<'_,AppDb>)->Result<(),String>{let name=name.trim();if name.is_empty(){return Err("El nombre no puede estar vacío".into())}lock_db(&state)?.execute("UPDATE subjects SET name=?1 WHERE id=?2",params![name,id]).map_err(|e|e.to_string())?;Ok(())}
#[tauri::command] fn delete_subject(id:i64,state:State<'_,AppDb>)->Result<(),String>{let conn=lock_db(&state)?;conn.execute("PRAGMA foreign_keys=ON",[]).map_err(|e|e.to_string())?;conn.execute("DELETE FROM subjects WHERE id=?1",[id]).map_err(|e|e.to_string())?;Ok(())}
#[tauri::command] fn list_topics(subject_id:i64,state:State<'_,AppDb>)->Result<Vec<Topic>,String>{let conn=lock_db(&state)?;let mut stmt=conn.prepare("SELECT t.id,t.subject_id,t.name,COUNT(r.id) FROM topics t LEFT JOIN resources r ON r.topic_id=t.id WHERE t.subject_id=?1 GROUP BY t.id ORDER BY t.name COLLATE NOCASE").map_err(|e|e.to_string())?;let rows=stmt.query_map([subject_id],|r|Ok(Topic{id:r.get(0)?,subject_id:r.get(1)?,name:r.get(2)?,resource_count:r.get(3)?})).map_err(|e|e.to_string())?;rows.collect::<Result<Vec<_>,_>>().map_err(|e|e.to_string())}
#[tauri::command] fn create_topic(subject_id:i64,name:String,state:State<'_,AppDb>)->Result<Topic,String>{let name=name.trim();if name.is_empty(){return Err("El nombre no puede estar vacío".into())}let conn=lock_db(&state)?;conn.execute("INSERT INTO topics(subject_id,name) VALUES(?1,?2)",params![subject_id,name]).map_err(|e|e.to_string())?;Ok(Topic{id:conn.last_insert_rowid(),subject_id,name:name.into(),resource_count:0})}
#[tauri::command] fn rename_topic(id:i64,name:String,state:State<'_,AppDb>)->Result<(),String>{let name=name.trim();if name.is_empty(){return Err("El nombre no puede estar vacío".into())}lock_db(&state)?.execute("UPDATE topics SET name=?1 WHERE id=?2",params![name,id]).map_err(|e|e.to_string())?;Ok(())}
#[tauri::command] fn delete_topic(id:i64,state:State<'_,AppDb>)->Result<(),String>{lock_db(&state)?.execute("DELETE FROM topics WHERE id=?1",[id]).map_err(|e|e.to_string())?;Ok(())}
#[tauri::command] fn list_resources(topic_id:i64,state:State<'_,AppDb>)->Result<Vec<Resource>,String>{let conn=lock_db(&state)?;let mut stmt=conn.prepare("SELECT id,topic_id,kind,title,content,path,updated_at FROM resources WHERE topic_id=?1 ORDER BY updated_at DESC,id DESC").map_err(|e|e.to_string())?;let rows=stmt.query_map([topic_id],|r|Ok(Resource{id:r.get(0)?,topic_id:r.get(1)?,kind:r.get(2)?,title:r.get(3)?,content:r.get(4)?,path:r.get(5)?,updated_at:r.get(6)?})).map_err(|e|e.to_string())?;rows.collect::<Result<Vec<_>,_>>().map_err(|e|e.to_string())}
#[tauri::command] fn save_resource(id:Option<i64>,topic_id:i64,kind:String,title:String,content:String,path:String,state:State<'_,AppDb>)->Result<i64,String>{if !["note","document","video","link","image"].contains(&kind.as_str()){return Err("Tipo de contenido no válido".into())}let title=title.trim();if title.is_empty(){return Err("El título no puede estar vacío".into())}let conn=lock_db(&state)?;if let Some(id)=id{conn.execute("UPDATE resources SET topic_id=?1,kind=?2,title=?3,content=?4,path=?5,updated_at=CURRENT_TIMESTAMP WHERE id=?6",params![topic_id,kind,title,content,path,id]).map_err(|e|e.to_string())?;Ok(id)}else{conn.execute("INSERT INTO resources(topic_id,kind,title,content,path) VALUES(?1,?2,?3,?4,?5)",params![topic_id,kind,title,content,path]).map_err(|e|e.to_string())?;Ok(conn.last_insert_rowid())}}
#[tauri::command] fn delete_resource(id:i64,state:State<'_,AppDb>)->Result<(),String>{lock_db(&state)?.execute("DELETE FROM resources WHERE id=?1",[id]).map_err(|e|e.to_string())?;Ok(())}
#[tauri::command] fn backup_database(destination:String,app:tauri::AppHandle,state:State<'_,AppDb>)->Result<(),String>{let source=app.path().app_data_dir().map_err(|e|e.to_string())?.join("organizador.sqlite");if !source.exists(){return Err("La base de datos todavía no existe".into())}let dest=PathBuf::from(destination);if let Some(parent)=dest.parent(){fs::create_dir_all(parent).map_err(|e|e.to_string())?}let conn=lock_db(&state)?;conn.execute_batch("PRAGMA wal_checkpoint(FULL);").map_err(|e|e.to_string())?;fs::copy(source,dest).map_err(|e|e.to_string())?;Ok(())}
pub fn run(){tauri::Builder::default().plugin(tauri_plugin_dialog::init()).plugin(tauri_plugin_opener::init()).setup(|app|{let dir=app.path().app_data_dir()?;fs::create_dir_all(&dir)?;let db_path=dir.join("organizador.sqlite");let conn=Connection::open(db_path)?;conn.execute_batch("PRAGMA foreign_keys=ON; PRAGMA journal_mode=WAL;")?;init_schema(&conn).map_err(std::io::Error::other)?;app.manage(AppDb(Mutex::new(conn)));Ok(())}).invoke_handler(tauri::generate_handler![initialize_database,list_subjects,create_subject,rename_subject,delete_subject,list_topics,create_topic,rename_topic,delete_topic,list_resources,save_resource,delete_resource,backup_database]).run(tauri::generate_context!()).expect("error al ejecutar Organizador Académico");}
